// ElevenLabs post-call webhook: map the analysis to the OS call record.
// Register as …/webhook/dp-elevenlabs-results?org=<company id>. Enable HMAC in ElevenLabs and keep this URL private.
const org = $('Incoming').first().json.query.org; const d = $json.body.data || {};
const vars = (d.conversation_initiation_client_data || {}).dynamic_variables || {};
const a = d.analysis || {}; const r = (a.data_collection_results || {});
const outcome = (r.outcome && r.outcome.value) || (a.call_successful === 'success' ? 'interested' : undefined);
return [{ json: { payload: { type: 'call_result', organization_id: org, call_id: vars.dp_call_id, status: d.status === 'failed' ? 'failed' : 'completed',
  ...(outcome ? { outcome } : {}), ...(a.transcript_summary ? { summary: String(a.transcript_summary).slice(0, 4000) } : {}) } } }];

// Signs one message for the OS inbound endpoint, exactly as the OS signs its webhooks.
const crypto = require('crypto');
const body = JSON.stringify($json.payload);
const ts = Math.floor(Date.now() / 1000);
const nonce = crypto.randomBytes(16).toString('hex');
const signature = crypto.createHmac('sha256', $env.DP_SIGNING_SECRET).update(`${ts}.${nonce}.${body}`).digest('hex');
return { json: { body, ts: String(ts), nonce, signature } };
